lib/app/http/controllers/auth.controller.dart<pre><code>import 'package:dox_auth/dox_auth.dart';
import 'package:dox_core/dox_core.dart';
import 'package:my_app/app/http/dtos/login_user.dto.dart';
import 'package:my_app/app/http/dtos/register_user.dto.dart';
import 'package:my_app/app/models/user/user.model.dart';

class AuthController {
  /// POST /api/auth/register
  Future&lt;Map&lt;String, dynamic&gt;&gt; register(RegisterUser body) async {
    User user = User()
      ..name = body.name
      ..email = body.email
      ..password = Hash.make(body.password);
    await user.save();

    String? token = Auth().login(user);
    return &lt;String, dynamic&gt;{'token': token, 'user': user};
  }

  /// POST /api/auth/login
  Future&lt;Map&lt;String, dynamic&gt;&gt; login(LoginUser body) async {
    Auth auth = Auth();
    String? token = await auth.attempt(&lt;String, dynamic&gt;{
      'email': body.email,
      'password': body.password,
    });
    if (token == null) {
      throw UnAuthorizedException(message: 'Wrong email or password');
    }
    return &lt;String, dynamic&gt;{'token': token, 'user': auth.user&lt;User&gt;()};
  }

  /// GET /api/auth/me (behind AuthMiddleware)
  User? me(DoxRequest req) {
    return req.auth?.user&lt;User&gt;();
  }

  /// POST /api/auth/logout (behind AuthMiddleware)
  /// A JWT can not be cancelled on the server. The client deletes the
  /// token. The token still works until `expiresIn` passes.
  Map&lt;String, String&gt; logout(DoxRequest req) {
    return &lt;String, String&gt;{'message': 'Delete the token on the client'};
  }
}

AuthController authController = AuthController();
</code></pre> <p><code>Hash.make</code> makes a bcrypt hash. <code>auth.attempt</code> finds the user by <code>email</code> and checks the password against that hash.</p>

packages/blog_shared/pubspec.yaml<pre><code>name: blog_shared
description: DTOs shared by the Dox server and the Flutter app.
version: 0.1.0
publish_to: none

environment:
  sdk: ^3.13.0

dependencies:
  dox_validation: ^3.0.0-alpha.4

dev_dependencies:
  build_runner: ^2.17.1
  dox_builder: ^3.0.0-alpha.4
</code></pre> <p><code>dox_builder</code> is a dev dependency. It only runs when you generate code. The Flutter app does not get it.</p> <p>Write the DTO. Import <code>dox_validation</code>, not <code>dox_core</code>:</p> packages/blog_shared/lib/src/save_blog.dart<pre><code>import 'package:dox_validation/dox_validation.dart';

part 'save_blog.g.dart';

/// A new blog post. The server and the app check it with the same rules.
@Dto()
class SaveBlog {
  @Trim()
  @Length(min: 3, max: 255)
  final String title;

  @Trim()
  @MinLength(10)
  final String description;

  const SaveBlog({required this.title, required this.description});

  static const DtoSchema&lt;SaveBlog&gt; schema = $SaveBlogDto;
}
</code></pre> <p>Export the DTOs. Also export <code>dox_validation</code>, so the app gets <code>ParseResult</code> and <code>ValidationException</code> from one import:</p> packages/blog_shared/lib/blog_shared.dart<pre><code>export 'package:dox_validation/dox_validation.dart';

export 'src/save_blog.dart';
</code></pre> <p>Generate the code:</p> <pre><code>cd packages/blog_shared
dart pub get
dart run build_runner build
</code></pre> <p>This writes two files:</p> <ul> <li><code>lib/src/save_blog.g.dart</code>: the checks, the converter and the JSON Schema of <code>SaveBlog</code>.</li> <li><code>lib/dtos.g.dart</code>: the list of every DTO in this package. The server uses it.</li> </ul> <p>Commit both files. Then the Flutter app does not need to run the generator.</p> <p>Rules that need the database stay on the server</p> <p><code>@Unique</code> and <code>@Exists</code> come from <code>dox_orm</code>. Do not use them in the shared package: the app can not import <code>dox_orm</code>. Check them on the server, in the service or in a server-only DTO. A <code>validate()</code> method that is <code>async</code> also can not run with <code>safeParse</code>. Use <code>safeParseAsync</code> for it.</p>

app/pubspec.yaml<pre><code>name: app
publish_to: none

environment:
  sdk: ^3.13.0

dependencies:
  flutter:
    sdk: flutter
  http: ^1.6.0
  blog_shared:
    path: ../packages/blog_shared
</code></pre> <p>The app does not depend on <code>dox_core</code>. It gets only <code>blog_shared</code> and <code>dox_validation</code>.</p> <p>One widget: it checks the form with <code>SaveBlog.schema.safeParse(...)</code>. It sends the request only when the input is good. <code>result.errors</code> has the same shape as the server's <code>422</code> body, so one <code>_errors</code> map shows both.</p> <p>Not run here</p> <p>The Flutter widget below was not run in a Flutter app. The same calls were run in a plain Dart program and in JavaScript (see below).</p> app/lib/new_blog_form.dart<pre><code>import 'dart:convert';

import 'package:blog_shared/blog_shared.dart';
import 'package:flutter/material.dart';
import 'package:http/http.dart' as http;

class NewBlogForm extends StatefulWidget {
  const NewBlogForm({super.key});

  @override
  State&lt;NewBlogForm&gt; createState() {
    return _NewBlogFormState();
  }
}

class _NewBlogFormState extends State&lt;NewBlogForm&gt; {
  final TextEditingController _title = TextEditingController();
  final TextEditingController _description = TextEditingController();
  Map&lt;String, String&gt; _errors = &lt;String, String&gt;{};

  Future&lt;void&gt; _submit() async {
    ParseResult&lt;SaveBlog&gt; result = SaveBlog.schema.safeParse(&lt;String, dynamic&gt;{
      'title': _title.text,
      'description': _description.text,
    });
    if (!result.success) {
      setState(() {
        _errors = result.errors;
      });
      return;
    }

    http.Response response = await http.post(
      Uri.parse('https://api.example.com/api/blogs'),
      headers: &lt;String, String&gt;{'Content-Type': 'application/json'},
      body: jsonEncode(SaveBlog.schema.toMap(result.value!)),
    );
    setState(() {
      _errors = response.statusCode == 422
          ? Map&lt;String, String&gt;.from(jsonDecode(response.body) as Map)
          : &lt;String, String&gt;{};
    });
  }

  @override
  void dispose() {
    _title.dispose();
    _description.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: &lt;Widget&gt;[
        TextField(
          controller: _title,
          decoration: InputDecoration(labelText: 'Title', errorText: _errors['title']),
        ),
        TextField(
          controller: _description,
          decoration: InputDecoration(labelText: 'Description', errorText: _errors['description']),
        ),
        ElevatedButton(onPressed: _submit, child: const Text('Save')),
      ],
    );
  }
}
